                    LidSettings lidSettings = new LidSettings(new LidTemperature(95,blockTypeData), true);
                    ProgStepHoldTime progStepHoldTime = new ProgStepHoldTime();
                    IncubationProg incubationProg = new IncubationProg(progSepTemperature, lidSettings, progStepHoldTime);
                    AdvancedList{ProgStartStopInfos} startList = new AdvancedList{ProgStartStopInfos}();
                    startList.Add(new ProgStartStopInfos(new BlockNumber(1), true));
//Stop program on the selected blocks
                    CheckStateResult communicationResult = blockCmds.StopProgramOnBlock(deviceDescription, incubationProg, startList, out DataSetList{BlockNumber} notStartedList);
                }
//This example stops the running program on the selected blocks.
            }

