This example shows how to call the method.             class Program
             {
                 static int Main()
                 {
//Read all available network adapters
                     AdvancedList{String} networkAdapaterList = NetworkHelperClass.GetAllNetworkDeviceDescriptions();
                     NetworkPort defaultPort = new NetworkPort(55555);
//Initialize communication parameters
                     DeviceComParams deviceComParams = new DeviceComParams(networkAdapaterList[0], defaultPort, defaultPort, EnCommunicationTimeout.TIMEOUT_1000ms);
                     ProgramCmds programCmds = new ProgramCmds(deviceComParams);
                     DeviceDescription deviceDescription = new DeviceDescription(new DeviceName("Testgerät"), new DeviceSerialNumber("1234567"));
                     UserInitials sourceDirectory = new UserInitials("XYZ");
                     ProgramNumber sourceProgNumber = new ProgramNumber(1);
                     UserInitials targetDirectory = new UserInitials("ABC");
                     ProgramNumber targetProgNumber = new ProgramNumber(10);
                     programCmds.CopyProgram_Finished += ProgramCmds_CopyProgram_Finished;
//Copy program
                     programCmds.CopyProgram(deviceDescription, sourceDirectory, sourceProgNumber, targetDirectory, targetProgNumber);
                 }
//This example copies the program with the number 1 from the user "XYZ" on the device "test device" to the directory of the user "ABC" to the program number 10

                 private void ProgramCmds_CopyProgram_Finished(object sender, DeviceComEventArgs e)
                 {
//Event method that is called when the background processing to copy the program is completed.
                 }
             }

This example shows how the method is called.            class Program
            {
                static int Main()
                {
//Read all available network adapters
                    AdvancedList{String} networkAdapaterList = NetworkHelperClass.GetAllNetworkDeviceDescriptions();
                    NetworkPort defaultPort = new NetworkPort(55555);
//Initialize communication parameters
                    DeviceComParams deviceComParams = new DeviceComParams(networkAdapaterList[0], defaultPort, defaultPort, EnCommunicationTimeout.TIMEOUT_1000ms);
                    ProgramCmds programCmds = new ProgramCmds(deviceComParams);
                    DeviceDescription deviceDescription = new DeviceDescription(new DeviceName("Testgerät"), new DeviceSerialNumber("1234567"));
//Get an overview of all available programs
                    UserInitials sourceDirectory = new UserInitials("XYZ");
                    CheckStateResult communicationResult = programCmds.GetProgramOverview(deviceDescription, sourceDirectory, out AdvancedList{ProgramInfos} programInfoList);
//Remove index 0 from the list, because this program should not be deleted
                    programInfoList.RemoveAt(0);
                    UserInitials targetDirectory = new UserInitials("ABC");
//Copy all programs from the programInfoList into the directory of the user "ABC
                    communicationResult = programCmds.CopyListOfPrograms(deviceDescription, programInfoList, targetDirectory, out DataSetList{ProgramInfos} notCopiedPrograms);
                }
//This example first retrieves an overview of all available programs of user "XYZ". The first program in the list is not to be copied to the directory of user "ABC", therefore it is deleted from the received overview list. All programs still present in the overview list are copied into the directory of user "ABC".
            }

This example shows how to call the method.            class Program
            {
                static int Main()
                {
//Read all available network adapters
                    AdvancedList{String} networkAdapaterList = NetworkHelperClass.GetAllNetworkDeviceDescriptions();
                    NetworkPort defaultPort = new NetworkPort(55555);
//Initialize communication parameters
                    DeviceComParams deviceComParams = new DeviceComParams(networkAdapaterList[0], defaultPort, defaultPort, EnCommunicationTimeout.TIMEOUT_1000ms);
                    ProgramCmds programCmds = new ProgramCmds(deviceComParams);
                    DeviceDescription sourceDevice = new DeviceDescription(new DeviceName("Testgerät"), new DeviceSerialNumber("1234567"));
//Get an overview of all available programs
                    UserInitials sourceDirectory = new UserInitials("XYZ");
                    CheckStateResult communicationResult = programCmds.GetProgramOverview(sourceDevice, sourceDirectory, out AdvancedList{ProgramInfos} programInfoList);
//Remove index 0 from the list, because this program should not be deleted
                    programInfoList.RemoveAt(0);
                    UserInitials targetDirectory = new UserInitials("ABC");
                    DeviceDescription targetDevice = new DeviceDescription(new DeviceName("Testgerät2"), new DeviceSerialNumber("1234557"));
//Copy all programs from the programInfoList into the directory of the user "ABC
