This example shows how to use the method.
            class Program
            {
                static int Main()
                {
                    //Alle verfügbaren Netzwerkadapter auslesen
                    AdvancedList{String} networkAdapaterList = NetworkHelperClass.GetAllNetworkDeviceDescriptions();
                    NetworkPort defaultPort = new NetworkPort(55555);
                    //Kommunikationsparameter initialisieren
                    UdpParams udpParams = new UdpParams(networkAdapaterList[0], defaultPort, defaultPort, EnCommunicationTimeout.TIMEOUT_1500ms);
                    //UDP-Client erzeugen
                    UdpClient udpClient = new UdpClient(udpParams);
                    //IP-Adresse erzeugen an die die Daten gesendet werden sollen
                    IPAddress sendAddress = IPAddress.Parse("192.168.2.5");
                    //Info Anfrage an die angegebene IP-Adresse senden
                    CheckStateResult sendResult = udpClient.SendString(sendAddress, "info\r\n");
                    CheckStateResult receiveResult = udpClient.ReceiveData(out AdvancedDictionary{String, String} receiveDataSet);
                }
                //Dieses Beispiel senden eine Info Anfrage an die angegebene IP-Adresse 192.168.2.5 und empfängt die Antwort
                //die vom Gerät zurückgesendet wurde
            }
